async function loadKioskConfig(){if(!kioskCode)return;try{const response=await fetch(`${api}?action=public-kiosk-config&code=${encodeURIComponent(kioskCode)}`,{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error||'โหลดการตั้งค่า Kiosk ไม่สำเร็จ');kioskConfig=body.template;kioskMenu=body.data||[];$('kioskPointName').textContent=kioskConfig.name;$('kioskBuildingLabel').textContent=kioskConfig.building_name+(kioskConfig.location_label?` · ${kioskConfig.location_label}`:'');renderKioskMenu(null)}catch(error){toast(error.message)}}
