function smartcardErrorMessage(error){const raw=String(error||'');const code=(raw.match(/0x[0-9a-f]{8}/i)||[])[0]?.toUpperCase();const messages={'0X80100069':'ไม่พบบัตรในเครื่องอ่าน กรุณาเสียบบัตรประชาชนให้สุดแล้วลองใหม่','0X8010000C':'ไม่พบบัตรประชาชน กรุณาเสียบบัตรแล้วลองใหม่','0X80100017':'ไม่พบเครื่องอ่านบัตร กรุณาตรวจสอบสายเชื่อมต่อ','0X8010001D':'บริการ Smart Card ไม่ทำงาน กรุณากดปุ่มรีเฟรชเครื่องอ่าน','0X8010002E':'ยังไม่มีเครื่องอ่านบัตรที่พร้อมใช้งาน'};if(code&&messages[code])return messages[code];if(/(?:เธ.|เน.){2,}/.test(raw)||raw.includes('�'))return 'อ่านบัตรไม่สำเร็จ กรุณาเสียบบัตรใหม่ หรือติดต่อเจ้าหน้าที่';return raw||'เครื่องอ่านบัตรยังไม่พร้อม กรุณาติดต่อเจ้าหน้าที่'}
async function checkBridge(){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),1800);try{const response=await fetch('http://127.0.0.1:17890/health',{cache:'no-store',signal:controller.signal});if(!response.ok)throw new Error();const health=await response.json();if(Number(health.bridge_version)<2){$('bridgeState').textContent='Bridge รุ่นเก่า · กรุณาติดตั้ง Smart Card Setup ใหม่';$('bridgeState').closest('.kiosk-place').classList.add('offline');return false}if(!health.reader_connected){$('bridgeState').textContent='ไม่พบเครื่องอ่านบัตร · กรุณาตรวจสาย USB';$('bridgeState').closest('.kiosk-place').classList.add('offline');return false}$('bridgeState').textContent=`เครื่องอ่านบัตรพร้อมใช้งาน${health.reader?` · ${health.reader}`:''}`;$('bridgeState').closest('.kiosk-place').classList.remove('offline');return true}catch{$('bridgeState').textContent='Bridge ไม่ตอบสนอง · Watchdog กำลังกู้คืน';$('bridgeState').closest('.kiosk-place').classList.add('offline');return false}finally{clearTimeout(timer)}}
$('restartBridge').onclick=async()=>{const button=$('restartBridge');button.disabled=true;$('bridgeState').textContent='กำลังรีสตาร์ต Smart Card…';try{const healthy=await checkBridge();if(healthy)await fetch('http://127.0.0.1:17890/restart',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}).catch(()=>{});await new Promise(resolve=>setTimeout(resolve,2500));for(let attempt=0;attempt<6;attempt++){if(await checkBridge()){toast('Smart Card Bridge พร้อมใช้งานแล้ว');return}await new Promise(resolve=>setTimeout(resolve,1000))}toast('Watchdog จะลองเริ่มระบบใหม่ภายใน 1 นาที')}finally{button.disabled=false}};
