function tokenFrom(value){const raw=value.trim();let token=raw;try{const url=new URL(raw);token=url.searchParams.get('t')||url.pathname.split('/').filter(Boolean).pop()||raw}catch{}return /^[a-f0-9]{32}$/i.test(token)?token.toLowerCase():token.toUpperCase()}
async function request(action,payload){const response=await fetch(`${api}?action=${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const body=await response.json();if(!response.ok)throw new Error(body.error||'ไม่สามารถดำเนินการได้');return body}
function setBusy(button,busy,label){button.disabled=busy;if(!button.dataset.label)button.dataset.label=button.textContent;button.textContent=busy?'กำลังดำเนินการ…':(label||button.dataset.label)}
$('scanForm').addEventListener('submit',async event=>{if(scanMode==='status')return;event.preventDefault();event.stopImmediatePropagation();const value=$('scanToken').value.trim();const digits=value.replace(/\D/g,'');const method=digits.length===13?'citizen':(/^0\d{8,9}$/.test(digits)?'phone':'code');$('scanError').classList.add('hidden');setBusy($('scanSubmit'),true);try{const body=await request('kiosk-lookup',{method,value});if(body.data.length!==1)throw new Error(body.data.length?'พบหลายรายการ กรุณากรอกรหัสอ้างอิง เบอร์มือถือ หรือเลขบัตรประชาชนให้ครบถ้วน':'ไม่พบรายการจองของวันนี้');showOnlineCheckinConfirmation(body.data[0])}catch(error){$('scanError').textContent=error.message;$('scanError').classList.remove('hidden')}finally{setBusy($('scanSubmit'),false,'ค้นหารายการจอง')}},true);
