function showOnlineCheckinConfirmation(row){pendingOnlineBooking=row;$('onlineCheckinName').textContent=row.customer_display||'ผู้รับบริการ';$('onlineCheckinDepartment').textContent=[row.department_name,row.service_name].filter(Boolean).join(' · ');$('onlineCheckinSlot').textContent=`${thaiBookingDate(row.slot_date)} เวลา ${String(row.start_time).slice(0,5)}–${String(row.end_time).slice(0,5)} น.`;$('onlineCheckinReference').textContent=row.reference_no||'—';$('onlineCheckinError').classList.add('hidden');$('onlineCheckinModal').classList.remove('hidden')}
