$('onlineCheckinModal').addEventListener('click',event=>{if(event.target===$('onlineCheckinModal'))closeOnlineCheckinConfirmation()});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('onlineCheckinModal').classList.contains('hidden'))closeOnlineCheckinConfirmation()});
$('confirmOnlineCheckin').onclick=async()=>{if(!pendingOnlineBooking)return;const button=$('confirmOnlineCheckin');setBusy(button,true);$('onlineCheckinError').classList.add('hidden');try{const body=await request('kiosk-check-in',{token:pendingOnlineBooking.public_id});closeOnlineCheckinConfirmation();renderTicket(body.ticket);setTimeout(()=>window.print(),350)}catch(error){$('onlineCheckinError').textContent=error.message;$('onlineCheckinError').classList.remove('hidden')}finally{setBusy(button,false,'ยืนยันการมาถึงและพิมพ์บัตรคิว')}};
$('scanForm').onsubmit=async event=>{event.preventDefault();const token=tokenFrom($('scanToken').value);$('scanError').classList.add('hidden');setBusy($('scanSubmit'),true);try{if(scanMode==='status'){if(/^[a-f0-9]{32}$/i.test(token)){location.href=`status.html?t=${encodeURIComponent(token.toLowerCase())}`;return}const body=await request('kiosk-lookup',{method:'code',value:token});if(body.data.length!==1)throw new Error(body.data.length?'พบมากกว่าหนึ่งคิว กรุณาค้นหาด้วย CID':'ไม่พบคิวของวันนี้');location.href=`status.html?t=${encodeURIComponent(body.data[0].queue_public_id||body.data[0].public_id)}`;return}const body=await request('kiosk-lookup',{method:'code',value:token});if(body.data.length!==1)throw new Error(body.data.length?'พบมากกว่าหนึ่งรายการ กรุณากรอกรหัสอ้างอิงให้ครบ':'ไม่พบรายการจองของวันนี้ กรุณาตรวจสอบวันและรหัสอ้างอิง');showOnlineCheckinConfirmation(body.data[0])}catch(error){$('scanError').textContent=error.message;$('scanError').classList.remove('hidden')}finally{setBusy($('scanSubmit'),false,scanMode==='status'?'ดูสถานะคิว':'ค้นหารายการจอง')}};
$('statusCitizenButton').onclick=()=>{lookupPurpose='status';lookupMethod='citizen';show('identifyPanel');$('lookupTitle').textContent='ค้นหาสถานะด้วยบัตรประชาชน';$('lookupSubtitle').textContent='เสียบบัตรประชาชน หรือกรอกเลข CID 13 หลัก';document.querySelectorAll('[data-method]').forEach(x=>x.classList.toggle('active',x.dataset.method==='citizen'));$('lookupLabel').childNodes[0].textContent='กรอกเลขบัตรประชาชน 13 หลัก';$('lookupValue').placeholder='X-XXXX-XXXXX-XX-X';$('lookupValue').inputMode='numeric';$('lookupValue').value='';$('lookupSubmit').textContent='ค้นหาสถานะคิว'};
function todayIso(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=type=>parts.find(x=>x.type===type).value;return `${get('year')}-${get('month')}-${get('day')}`}
async function loadSlots(autoIssue=true){$('slotCards').innerHTML='<div class="loading-card">กำลังตรวจสอบช่วงลงทะเบียน…</div>';$('walkinError').classList.add('hidden');try{const query=new URLSearchParams({action:'public-slots',date:todayIso()});if(kioskCode)query.set('kiosk',kioskCode);if(selectedDepartmentId)query.set('department_id',selectedDepartmentId);if(selectedServiceId)query.set('service_id',selectedServiceId);const response=await fetch(`${api}?${query}`,{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error);if(!body.data.length){$('slotCards').innerHTML='<section class="slot-unavailable" role="alert" aria-live="assertive"><span class="slot-unavailable-icon" aria-hidden="true">!</span><div><small>ไม่สามารถออกบัตรคิวได้ในขณะนี้</small><h2>วันนี้ไม่มีช่วงลงทะเบียน<br>ที่ยังรับคิวเพิ่ม</h2><strong>กรุณาติดต่อเจ้าหน้าที่ห้องบัตร</strong><p>เจ้าหน้าที่จะตรวจสอบช่วงเวลาและแนะนำจุดบริการที่เหมาะสมให้ท่าน</p></div></section>';return}$('slotCards').innerHTML=body.data.map(x=>`<button type="button" class="slot-card" data-slot="${x.id}"><span>${x.start_time.slice(0,5)}–${x.end_time.slice(0,5)} น.</span><strong>${escapeHtml(x.department_name)}</strong><small>${escapeHtml(x.service_name||'บริการทั่วไป')} · ${body.data.length===1?'กำลังออกบัตรคิว':'แตะเพื่อรับและพิมพ์บัตรคิว'}</small><em><span>${x.is_unlimited?'จำนวนรับ':'รับได้อีก'}</span><b>${x.is_unlimited?'ไม่จำกัดคิว':`${Number(x.available_count)} คิว`}</b></em></button>`).join('');const cards=[...document.querySelectorAll('.slot-card')];cards.forEach(card=>card.onclick=()=>issueWalkinQueue(card));if(autoIssue&&cards.length===1)await issueWalkinQueue(cards[0])}catch(error){$('slotCards').innerHTML=`<div class="loading-card">${escapeHtml(error.message)}</div>`}}
async function issueWalkinQueue(card){if(issuingTicket)return;issuingTicket=true;$('walkinError').classList.add('hidden');document.querySelectorAll('.slot-card').forEach(button=>button.disabled=true);card.classList.add('selected');card.querySelector('small').textContent='กำลังออกบัตรคิว…';if(!currentRequestKey)currentRequestKey=crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`;try{const body=await request('kiosk-walk-in',{slot_id:+card.dataset.slot,menu_item_id:selectedMenuItemId,customer_name:lastCardName||'ผู้รับบริการ',customer_phone:'',citizen_id:lastCitizenId,idempotency_key:currentRequestKey});if(lastCitizenId)await request('hosxp-link',{token:body.ticket.public_id,citizen_id:lastCitizenId}).catch(()=>{});renderTicket(body.ticket)}catch(error){issuingTicket=false;await loadSlots(false);$('walkinError').textContent=error.message;$('walkinError').classList.remove('hidden')}}
function escapeHtml(value){const node=document.createElement('span');node.textContent=value??'';return node.innerHTML}
document.querySelectorAll('[data-method]').forEach(button=>button.onclick=()=>{lookupMethod=button.dataset.method;document.querySelectorAll('[data-method]').forEach(x=>x.classList.toggle('active',x===button));const config={code:['กรอกรหัสคิวหรือรหัสยืนยัน','ตัวอย่าง KQ-261016-ABC123','text'],citizen:['กรอกเลขบัตรประชาชน 13 หลัก','X-XXXX-XXXXX-XX-X','numeric'],phone:['กรอกหมายเลขโทรศัพท์','0XX-XXX-XXXX','tel']}[lookupMethod];$('lookupLabel').childNodes[0].textContent=config[0];$('lookupValue').placeholder=config[1];$('lookupValue').inputMode=config[2];$('lookupValue').value='';$('lookupResults').classList.add('hidden');$('lookupError').classList.add('hidden')});
async function lookupBooking(method,value){setBusy($('lookupSubmit'),true);$('lookupError').classList.add('hidden');$('lookupResults').classList.add('hidden');try{const body=await request('kiosk-lookup',{method,value});renderLookupResults(body.data,method,value)}catch(error){$('lookupError').textContent=error.message;$('lookupError').classList.remove('hidden')}finally{setBusy($('lookupSubmit'),false,lookupPurpose==='status'?'ค้นหาสถานะคิว':'ค้นหาคิว')}}
$('lookupForm').onsubmit=event=>{event.preventDefault();lookupBooking(lookupMethod,$('lookupValue').value)};
function renderLookupResults(rows,method,value){$('lookupResults').classList.remove('hidden');if(!rows.length){const cardNotice=method==='citizen'&&lastCitizenId?`<div class="card-identity"><strong>อ่านบัตรสำเร็จ</strong><span>${escapeHtml(lastCardName||'ผู้ถือบัตร')} · CID •••••••••${lastCitizenId.slice(-4)}</span></div>`:'';$('lookupResults').innerHTML=cardNotice+`<div class="no-booking"><strong>ไม่พบคิวของวันนี้</strong><p>${lookupPurpose==='status'?'กรุณาตรวจสอบข้อมูล หรือติดต่อเจ้าหน้าที่':'สามารถเลือกรับคิว Walk-in ได้'}</p>${lookupPurpose==='status'?'':'<button type="button" class="touch-button secondary" id="continueWalkin">เลือกบริการ Walk-in</button>'}</div>`;if($('continueWalkin'))$('continueWalkin').onclick=async()=>{if(!lastCardName)lastCardName='ผู้รับบริการไม่ใช้บัตรประชาชน';updatePatientSummary();await kioskConfigReady;renderKioskMenu(null);show('servicePanel')};return}$('lookupResults').innerHTML=rows.map((row,index)=>`<article class="booking-result"><strong>${escapeHtml(row.customer_display)} · ${escapeHtml(row.department_name)}</strong><span>${escapeHtml(row.queue_no||row.reference_no)} · ${row.start_time.slice(0,5)}–${row.end_time.slice(0,5)} น.</span><div class="booking-result-actions"><button type="button" class="touch-button secondary" data-view-status="${index}">ดูสถานะคิว</button>${lookupPurpose==='status'?'':`<button type="button" class="touch-button primary" data-checkin="${index}">ยืนยันว่ามาถึงแล้ว</button>`}</div></article>`).join('');document.querySelectorAll('[data-view-status]').forEach(button=>button.onclick=async()=>{const row=rows[+button.dataset.viewStatus];setBusy(button,true);if(method==='citizen'&&row.queue_public_id)await request('hosxp-link',{token:row.queue_public_id,citizen_id:value}).catch(()=>{});location.href=`status.html?t=${encodeURIComponent(row.queue_public_id||row.public_id)}`});document.querySelectorAll('[data-checkin]').forEach(button=>button.onclick=()=>showOnlineCheckinConfirmation(rows[+button.dataset.checkin]))}
$('smartcardButton').onclick=async()=>{const button=$('smartcardButton');button.disabled=true;$('readerState').textContent='กำลังอ่านบัตร…';toast('กำลังอ่านบัตรประชาชน…');try{const response=await fetch('http://127.0.0.1:17890/read',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const body=await response.json();if(!response.ok||!body.data?.citizen_id)throw new Error(body.error||'อ่านบัตรไม่สำเร็จ');await acceptCard(body.data)}catch(error){const message=smartcardErrorMessage(error.message);$('readerState').textContent=message;toast(message)}finally{button.disabled=false}};
function renderTicket(ticket){const start=String(ticket.start_time||'').slice(0,5),end=String(ticket.end_time||'').slice(0,5),queueNo=ticket.queue_no||'—';$('ticketNo').textContent=queueNo;$('ticketNo').classList.toggle('queue-number-long',Array.from(queueNo).length>7);$('ticketDepartment').textContent=ticket.department_name||'จุดบริการ';$('ticketService').textContent=ticket.service_name||'';$('ticketSlot').textContent=start&&end?`ช่วงลงทะเบียน ${start}–${end} น.`:'รอเจ้าหน้าที่แจ้งช่วงลงทะเบียน';$('ticketDate').textContent=ticket.slot_date?new Intl.DateTimeFormat('th-TH',{timeZone:'Asia/Bangkok',dateStyle:'long'}).format(new Date(`${ticket.slot_date}T12:00:00+07:00`)):'';$('ticketReference').textContent=ticket.reference_no?`เลขอ้างอิง ${ticket.reference_no}`:'';const url=new URL('status.html',location.href);url.searchParams.set('t',ticket.public_id);$('statusLink').href=url.href;$('ticketToken').textContent=ticket.public_id;const qr=qrcode(0,'M');qr.addData(url.href);qr.make();$('ticketQr').src=qr.createDataURL(7,10);show('ticketPanel');finishSeconds=60;$('finishCountdown').textContent=finishSeconds;finishTimer=setInterval(()=>{finishSeconds--;$('finishCountdown').textContent=finishSeconds;if(finishSeconds<=0)show('homePanel')},1000)}
async function stopCamera(){if(stream){stream.getTracks().forEach(track=>track.stop());stream=null}$('video').classList.add('hidden');$('cameraIdle').classList.remove('hidden')}
function handleScanned(value){$('scanToken').value=tokenFrom(value);stopCamera();$('scanForm').requestSubmit()}
$('cameraButton').onclick=async()=>{if(!navigator.mediaDevices?.getUserMedia){$('scanError').textContent='เบราว์เซอร์นี้ไม่สามารถเปิดกล้องได้ กรุณาใช้เครื่องสแกนหรือกรอกรหัส';$('scanError').classList.remove('hidden');return}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}}});$('video').srcObject=stream;await $('video').play();$('video').classList.remove('hidden');$('cameraIdle').classList.add('hidden');const detector='BarcodeDetector'in window?new BarcodeDetector({formats:['qr_code']}):null;const canvas=document.createElement('canvas'),context=canvas.getContext('2d',{willReadFrequently:true});let lastFallback=0;const scan=async time=>{if(!stream)return;if(detector){const codes=await detector.detect($('video')).catch(()=>[]);if(codes[0]){handleScanned(codes[0].rawValue);return}}else if(typeof jsQR==='function'&&time-lastFallback>120&&$('video').videoWidth){lastFallback=time;canvas.width=$('video').videoWidth;canvas.height=$('video').videoHeight;context.drawImage($('video'),0,0,canvas.width,canvas.height);const image=context.getImageData(0,0,canvas.width,canvas.height);const code=jsQR(image.data,image.width,image.height,{inversionAttempts:'dontInvert'});if(code?.data){handleScanned(code.data);return}}requestAnimationFrame(scan)};requestAnimationFrame(scan)}catch{$('scanError').textContent='ไม่สามารถเปิดกล้องได้ กรุณาอนุญาตการใช้กล้อง หรือใช้เครื่องสแกน/กรอกรหัสแทน';$('scanError').classList.remove('hidden')}};
let scannerBuffer='',scannerAt=0;document.addEventListener('keydown',event=>{if(event.target.matches('input'))return;const now=Date.now();if(now-scannerAt>100)scannerBuffer='';scannerAt=now;if(event.key==='Enter'&&scannerBuffer.length>8){handleScanned(scannerBuffer);scannerBuffer=''}else if(event.key.length===1)scannerBuffer+=event.key});
